UPDATE public.faqs SET question = 'Bagaimana cara mulai berlangganan?', answer = 'Hubungi kami lewat WhatsApp atau surel, ceritakan kebutuhan Anda, sepakati biayanya, lalu lakukan pembayaran manual. Setelah terkonfirmasi, organisasi Anda kami aktifkan paling lambat 1x24 jam dan berjalan terus.', updated_at = now() WHERE id = '63f24875-3436-4a7f-b730-4441c0106a1c' AND question = 'Bagaimana cara mulai berlangganan?';--> statement-breakpoint
UPDATE public.faqs SET question = 'Apakah langganan bisa kedaluwarsa?', answer = 'Tidak ada masa aktif yang kedaluwarsa dan tidak ada masa tenggang: selama status organisasi Anda aktif, seluruh fungsi berjalan penuh. Penonaktifan hanya terjadi atas permintaan Anda atau pelanggaran ketentuan.', updated_at = now() WHERE id = '2a0f30ac-20aa-4971-9502-944c35c1c705' AND question = 'Apa yang terjadi kalau masa aktif habis?';--> statement-breakpoint
UPDATE public.faqs SET question = 'Apakah ada tingkatan paket?', answer = 'Tidak ada. Semua pelanggan mendapat fungsi yang sama; yang membedakan hanya kebutuhan Anda yang kami diskusikan di awal. Satu-satunya hal yang disesuaikan adalah biaya kesepakatan.', updated_at = now() WHERE id = '64c110a9-da4b-4e9f-9be8-1190096ad96a' AND question = 'Bisakah naik atau turun paket di tengah jalan?';--> statement-breakpoint
UPDATE public.faqs SET question = 'Berapa biayanya?', answer = 'Hubungi kami lewat WhatsApp, ceritakan kebutuhan dan jumlah websitenya. Kami memberi angka pasti di depan sebelum Anda membayar apa pun.', updated_at = now() WHERE id = '761e83a9-b50d-4766-81c9-efd5652642cd' AND question = 'Bagaimana paket Enterprise bekerja?';--> statement-breakpoint
UPDATE public.faqs SET answer = 'Bisa. Ceritakan sistem lama Anda saat menghubungi kami; bantuan pindahan kami sesuaikan dengan kebutuhan.', updated_at = now() WHERE id = '1de04400-5846-4d71-a6e4-b66668c3fc76' AND question = 'Saya sudah punya website berjalan. Bisa pindah?';--> statement-breakpoint
UPDATE public.faqs SET answer = 'Tidak ada trial otomatis. Sebagai gantinya Anda bisa melihat cara kerja dasbor lewat sesi peninjauan bersama sebelum memutuskan.', updated_at = now() WHERE id = 'acd28953-8f62-42a8-9e11-9916dd86b793' AND question = 'Apakah ada masa percobaan gratis?';--> statement-breakpoint
UPDATE public.faqs SET answer = 'Semua pelanggan didampingi manusia lewat kanal yang jelas — bukan bot. Prioritas penanganan mengikuti dampak: situs tidak bisa diakses ditangani lebih dulu.', updated_at = now() WHERE id = 'd849d3fe-c818-469d-bc54-10aa1b8dd235' AND question = 'Bagaimana kalau butuh bantuan?';--> statement-breakpoint
